#!/usr/bin/env python3
"""lpgcov.py FILE.gcov...  The gcov listing of a file generated by patsopt --gline has several entries for a line of the ATS source
(one per C line mapped to it, one per instance of a template): a line is covered when one of its entries was executed.
Prints, for each file, the numbers of executable and covered lines and the lines that were never executed."""
import sys, re
tot = 0; totc = 0
for fn in sys.argv[1:]:
    cnt = {}
    text = {}
    for l in open(fn, errors='replace'):
        m = re.match(r'^\s*([0-9#=\-*]+)\*?:\s*(\d+):(.*)$', l.rstrip('\n'))
        if not m: continue
        c, no, t = m.group(1), int(m.group(2)), m.group(3)
        if no == 0 or c == '-': continue
        text[no] = t
        if c in ('#####', '====='): cnt.setdefault(no, 0)
        else: cnt[no] = max(cnt.get(no, 0), int(c.rstrip('*')))
    ex = sorted(no for no in cnt)
    cov = [no for no in ex if cnt[no] > 0]
    un = [no for no in ex if cnt[no] == 0]
    tot += len(ex); totc += len(cov)
    print('%s: %d executable lines, %d covered' % (fn.replace('.gcov', ''), len(ex), len(cov)))
    for no in un: print('  %d:%s' % (no, text[no][:110]))
print('total: %d executable lines, %d covered' % (tot, totc))
